import{_ as t,c as h,o as i,a2 as o}from"./chunks/framework.B7el9cAC.js";const d=JSON.parse('{"title":"Mục 2.1 – Thiết Bị Mạng","description":"","frontmatter":{},"headers":[],"relativePath":"chuong-2/2.1-thiet-bi-mang.md","filePath":"chuong-2/2.1-thiet-bi-mang.md","lastUpdated":1775359730000}'),a={name:"chuong-2/2.1-thiet-bi-mang.md"};function r(g,n,c,e,s,u){return i(),h("div",null,[...n[0]||(n[0]=[o(`<h1 id="muc-2-1-–-thiet-bi-mang" tabindex="-1">Mục 2.1 – Thiết Bị Mạng <a class="header-anchor" href="#muc-2-1-–-thiet-bi-mang" aria-label="Permalink to &quot;Mục 2.1 – Thiết Bị Mạng&quot;">​</a></h1><blockquote><p><strong>Chương 2: Mạng máy tính và Internet</strong></p></blockquote><hr><h2 id="🔹-1-gioi-thieu-sieu-co-ban" tabindex="-1">🔹 1. GIỚI THIỆU SIÊU CƠ BẢN <a class="header-anchor" href="#🔹-1-gioi-thieu-sieu-co-ban" aria-label="Permalink to &quot;🔹 1. GIỚI THIỆU SIÊU CƠ BẢN&quot;">​</a></h2><h3 id="tai-sao-can-biet-ve-thiet-bi-mang" tabindex="-1">Tại sao cần biết về thiết bị mạng? <a class="header-anchor" href="#tai-sao-can-biet-ve-thiet-bi-mang" aria-label="Permalink to &quot;Tại sao cần biết về thiết bị mạng?&quot;">​</a></h3><p>Hãy tưởng tượng buổi sáng bạn mở điện thoại lên, mở YouTube xem video – chỉ trong vài giây, hình ảnh và âm thanh từ máy chủ ở tận Mỹ xuất hiện ngay trên màn hình. Điều đó xảy ra được là nhờ <strong>một chuỗi thiết bị mạng</strong> làm việc phối hợp với nhau trong im lặng.</p><p>Thử nghĩ về bưu điện trong cuộc sống thực:</p><ul><li><strong>Modem</strong> giống như cổng ra vào của tòa nhà – nơi thư từ bên ngoài đi vào.</li><li><strong>Router</strong> giống như nhân viên bưu điện – họ đọc địa chỉ và quyết định thư đi về hướng nào.</li><li><strong>Switch</strong> giống như thùng thư nội bộ trong tòa nhà – phân phát đúng tầng, đúng phòng.</li><li><strong>Access Point</strong> giống như loa phát thanh không dây – để ai trong phạm vi cũng nhận được tín hiệu.</li></ul><p>Nếu không có những thiết bị này, máy tính của bạn sẽ là một hòn đảo cô lập – không thể nói chuyện với ai.</p><hr><h2 id="🔹-2-ly-thuyet-chi-tiet" tabindex="-1">🔹 2. LÝ THUYẾT CHI TIẾT <a class="header-anchor" href="#🔹-2-ly-thuyet-chi-tiet" aria-label="Permalink to &quot;🔹 2. LÝ THUYẾT CHI TIẾT&quot;">​</a></h2><h3 id="_2-1-switch-bo-chuyen-mach" tabindex="-1">2.1 Switch (Bộ chuyển mạch) <a class="header-anchor" href="#_2-1-switch-bo-chuyen-mach" aria-label="Permalink to &quot;2.1 Switch (Bộ chuyển mạch)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Switch là thiết bị mạng dùng để <strong>kết nối nhiều thiết bị trong cùng một mạng nội bộ (LAN)</strong> với nhau.</p><ul><li>Hoạt động ở <strong>Tầng 2 (Data Link Layer)</strong> trong mô hình OSI.</li><li>Dùng <strong>địa chỉ MAC</strong> để nhận diện thiết bị.</li><li>Truyền dữ liệu <strong>trực tiếp từ thiết bị nguồn đến thiết bị đích</strong> mà không phát tán ra toàn mạng.</li><li>Có nhiều cổng (port): 8, 16, 24, 48 cổng.</li></ul><h3 id="_2-2-router-bo-đinh-tuyen" tabindex="-1">2.2 Router (Bộ định tuyến) <a class="header-anchor" href="#_2-2-router-bo-đinh-tuyen" aria-label="Permalink to &quot;2.2 Router (Bộ định tuyến)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Router là thiết bị kết nối <strong>các mạng khác nhau</strong> lại với nhau – điển hình là kết nối mạng nội bộ (LAN) với Internet (WAN).</p><ul><li>Hoạt động ở <strong>Tầng 3 (Network Layer)</strong> trong mô hình OSI.</li><li>Dùng <strong>địa chỉ IP</strong> để định tuyến gói tin.</li><li>Có khả năng <strong>NAT</strong> (Network Address Translation) – dịch địa chỉ IP nội bộ sang địa chỉ IP công cộng.</li><li>Có tính năng <strong>tường lửa</strong> (firewall) cơ bản.</li></ul><h3 id="_2-3-access-point-điem-truy-cap-khong-day" tabindex="-1">2.3 Access Point (Điểm truy cập không dây) <a class="header-anchor" href="#_2-3-access-point-điem-truy-cap-khong-day" aria-label="Permalink to &quot;2.3 Access Point (Điểm truy cập không dây)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Access Point (AP) là thiết bị <strong>phát sóng Wi-Fi</strong>, cho phép thiết bị không dây kết nối vào mạng có dây.</p><ul><li>Về bản chất, AP là một cầu nối giữa mạng có dây và thiết bị không dây.</li><li>Router Wi-Fi gia đình thường <strong>tích hợp sẵn Access Point</strong> bên trong.</li><li>Trong môi trường lớn (trường học, sân bay), người ta dùng nhiều AP riêng biệt để phủ sóng.</li></ul><h3 id="_2-4-modem-bo-đieu-giai" tabindex="-1">2.4 Modem (Bộ điều giải) <a class="header-anchor" href="#_2-4-modem-bo-đieu-giai" aria-label="Permalink to &quot;2.4 Modem (Bộ điều giải)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Modem viết tắt của <strong>Modulator-Demodulator</strong> – thiết bị chuyển đổi tín hiệu số của máy tính thành tín hiệu analog (hoặc quang) để truyền qua đường dây viễn thông, và ngược lại.</p><ul><li><strong>Modulate (điều chế):</strong> Chuyển tín hiệu số → tín hiệu analog để truyền đi.</li><li><strong>Demodulate (giải điều chế):</strong> Nhận tín hiệu analog → chuyển lại thành tín hiệu số.</li><li>Kết nối với nhà cung cấp dịch vụ Internet (ISP) qua đường cáp đồng, cáp quang, hoặc đường dây điện thoại.</li></ul><h3 id="_2-5-đia-chi-mac-media-access-control" tabindex="-1">2.5 Địa chỉ MAC (Media Access Control) <a class="header-anchor" href="#_2-5-đia-chi-mac-media-access-control" aria-label="Permalink to &quot;2.5 Địa chỉ MAC (Media Access Control)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Địa chỉ MAC là <strong>định danh vật lý duy nhất</strong> được gắn cố định vào card mạng của mỗi thiết bị khi sản xuất.</p><ul><li>Dài <strong>48 bit</strong>, viết dưới dạng 6 cặp số hex, ví dụ: <code>A4:C3:F0:85:AC:5D</code></li><li><strong>Không thể thay đổi</strong> (về lý thuyết) – gắn liền với phần cứng.</li><li>Chỉ có giá trị trong <strong>mạng nội bộ</strong> – không được định tuyến qua Internet.</li><li>Switch dùng MAC để xây dựng <strong>bảng MAC (MAC table)</strong> và chuyển frame đúng cổng.</li></ul><h3 id="_2-6-đia-chi-ip-internet-protocol" tabindex="-1">2.6 Địa chỉ IP (Internet Protocol) <a class="header-anchor" href="#_2-6-đia-chi-ip-internet-protocol" aria-label="Permalink to &quot;2.6 Địa chỉ IP (Internet Protocol)&quot;">​</a></h3><p><strong>Định nghĩa:</strong> Địa chỉ IP là <strong>địa chỉ logic</strong> được gán cho thiết bị để định danh trong mạng, có thể thay đổi tùy cấu hình.</p><ul><li><strong>IPv4:</strong> 32 bit, viết dạng 4 octet thập phân, ví dụ: <code>192.168.1.10</code></li><li><strong>IPv6:</strong> 128 bit, ví dụ: <code>2001:0db8:85a3::8a2e:0370:7334</code></li><li>Có hai loại: <ul><li><strong>IP công cộng (Public IP):</strong> Dùng trên Internet, duy nhất toàn cầu.</li><li><strong>IP nội bộ (Private IP):</strong> Dùng trong LAN, ví dụ dải <code>192.168.x.x</code>, <code>10.x.x.x</code>.</li></ul></li><li>Router dùng IP để <strong>định tuyến</strong> gói tin giữa các mạng.</li></ul><hr><h2 id="🔹-3-giai-thich-ban-chat" tabindex="-1">🔹 3. GIẢI THÍCH BẢN CHẤT <a class="header-anchor" href="#🔹-3-giai-thich-ban-chat" aria-label="Permalink to &quot;🔹 3. GIẢI THÍCH BẢN CHẤT&quot;">​</a></h2><h3 id="thuc-chat-switch-va-router-la-gi" tabindex="-1">Thực chất Switch và Router là gì? <a class="header-anchor" href="#thuc-chat-switch-va-router-la-gi" aria-label="Permalink to &quot;Thực chất Switch và Router là gì?&quot;">​</a></h3><p><strong>Switch</strong> chỉ &quot;nhìn&quot; vào phần <strong>tên cụ thể của thiết bị</strong> (địa chỉ MAC) – giống như người đưa thư trong một tòa nhà, chỉ cần biết số phòng là đủ, không cần biết tòa nhà đó ở quận nào.</p><p><strong>Router</strong> thì &quot;nhìn&quot; vào <strong>địa chỉ toàn cầu</strong> (địa chỉ IP) – giống như bưu điện trung tâm, cần biết cả tên đường, quận, thành phố để quyết định gửi gói hàng đi đường nào là nhanh nhất.</p><p><strong>Modem</strong> là &quot;phiên dịch viên&quot; – nhà cung cấp mạng (ISP) dùng tín hiệu điện/quang trên đường dây, còn máy tính dùng tín hiệu số. Modem đứng giữa và dịch qua lại liên tục.</p><p><strong>Access Point</strong> là &quot;chiếc loa không dây&quot; – thay vì bắt bạn phải cắm dây, nó phát sóng ra xung quanh để thiết bị tự bắt tín hiệu.</p><hr><h2 id="🔹-4-luong-hoat-đong-step-by-step" tabindex="-1">🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP <a class="header-anchor" href="#🔹-4-luong-hoat-đong-step-by-step" aria-label="Permalink to &quot;🔹 4. LUỒNG HOẠT ĐỘNG STEP-BY-STEP&quot;">​</a></h2><h3 id="luong-du-lieu-tu-internet-đen-may-tinh-cua-ban" tabindex="-1">Luồng dữ liệu từ Internet đến máy tính của bạn <a class="header-anchor" href="#luong-du-lieu-tu-internet-đen-may-tinh-cua-ban" aria-label="Permalink to &quot;Luồng dữ liệu từ Internet đến máy tính của bạn&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Internet → Modem → Router → Switch → Thiết bị đầu cuối</span></span></code></pre></div><p><strong>Bước 1 – Internet đến Modem:</strong> Nhà cung cấp dịch vụ Internet (VNPT, Viettel, FPT...) truyền dữ liệu qua cáp quang/đồng đến nhà bạn. Modem nhận tín hiệu này và <strong>chuyển đổi thành tín hiệu số</strong> mà router có thể hiểu.</p><p><strong>Bước 2 – Modem đến Router:</strong> Router nhận dữ liệu từ modem, đọc <strong>địa chỉ IP đích</strong>, xác định xem gói tin đó thuộc về thiết bị nào trong mạng nội bộ.</p><p><strong>Bước 3 – Router đến Switch:</strong> Router chuyển gói tin vào mạng nội bộ. Nếu là kết nối có dây, gói tin đến <strong>Switch</strong>. Router biết thiết bị đó có IP nội bộ là <code>192.168.1.5</code>, chuyển gói đến switch.</p><p><strong>Bước 4 – Switch đến Thiết bị:</strong> Switch tra <strong>bảng MAC</strong> để biết địa chỉ MAC của thiết bị có IP <code>192.168.1.5</code> đang ở cổng số mấy, rồi chuyển frame <strong>chính xác đến cổng đó</strong> – không phát tán sang các thiết bị khác.</p><p><strong>Bước 5 – Thiết bị nhận dữ liệu:</strong> Máy tính/điện thoại nhận frame, xử lý và hiển thị kết quả (trang web, video, email...).</p><blockquote><p><strong>Nếu dùng Wi-Fi:</strong> Bước 3-4 thay bằng Router/Access Point phát sóng Wi-Fi trực tiếp đến thiết bị.</p></blockquote><hr><h2 id="🔹-5-vi-du-minh-hoa" tabindex="-1">🔹 5. VÍ DỤ MINH HỌA <a class="header-anchor" href="#🔹-5-vi-du-minh-hoa" aria-label="Permalink to &quot;🔹 5. VÍ DỤ MINH HỌA&quot;">​</a></h2><h3 id="vi-du-1-–-co-ban-mang-tai-nha" tabindex="-1">Ví dụ 1 – Cơ bản: Mạng tại nhà <a class="header-anchor" href="#vi-du-1-–-co-ban-mang-tai-nha" aria-label="Permalink to &quot;Ví dụ 1 – Cơ bản: Mạng tại nhà&quot;">​</a></h3><p>Nhà bạn có: 1 modem, 1 router Wi-Fi, 1 switch 8 cổng, 3 máy tính, 2 điện thoại.</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Internet/ISP]</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   [Modem]        ← Nhận tín hiệu từ ISP, chuyển đổi tín hiệu</span></span>
<span class="line"><span>      |</span></span>
<span class="line"><span>   [Router]       ← Phân chia mạng nội bộ, cấp IP cho thiết bị</span></span>
<span class="line"><span>    /    \\</span></span>
<span class="line"><span>[Switch] [Wi-Fi AP]</span></span>
<span class="line"><span>  / | \\      |  \\</span></span>
<span class="line"><span>[PC1][PC2][PC3] [Phone1][Phone2]</span></span></code></pre></div><ul><li>PC1, PC2, PC3 cắm dây vào switch → switch dùng MAC để phân phát.</li><li>Phone1, Phone2 kết nối Wi-Fi → router/AP dùng IP để định tuyến.</li></ul><h3 id="vi-du-2-–-thuc-te-quan-ca-phe" tabindex="-1">Ví dụ 2 – Thực tế: Quán cà phê <a class="header-anchor" href="#vi-du-2-–-thuc-te-quan-ca-phe" aria-label="Permalink to &quot;Ví dụ 2 – Thực tế: Quán cà phê&quot;">​</a></h3><p>Quán cà phê có 30 khách hàng dùng Wi-Fi cùng lúc:</p><ul><li><strong>1 modem</strong> kết nối đường truyền cáp quang từ ISP.</li><li><strong>1 router</strong> quản lý toàn bộ mạng, cấp IP tự động cho khách (DHCP).</li><li><strong>3 Access Point</strong> đặt ở 3 góc quán để phủ sóng đồng đều.</li><li>Mỗi khách có <strong>IP nội bộ</strong> riêng (ví dụ: <code>192.168.1.100</code> đến <code>192.168.1.130</code>).</li><li>Tất cả dùng <strong>1 IP công cộng</strong> duy nhất khi ra Internet (nhờ NAT của router).</li></ul><h3 id="vi-du-3-–-nang-cao-truong-hoc" tabindex="-1">Ví dụ 3 – Nâng cao: Trường học <a class="header-anchor" href="#vi-du-3-–-nang-cao-truong-hoc" aria-label="Permalink to &quot;Ví dụ 3 – Nâng cao: Trường học&quot;">​</a></h3><p>Trường có 40 phòng học, mỗi phòng 30 máy tính:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[ISP - Cáp quang tốc độ cao]</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>    [Modem quang]</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>  [Router trung tâm]  ← IP công cộng, kết nối Internet</span></span>
<span class="line"><span>         |</span></span>
<span class="line"><span>  [Core Switch]       ← Switch tốc độ cao, kết nối toàn trường</span></span>
<span class="line"><span>    /    |    \\</span></span>
<span class="line"><span>[Switch  Switch  Switch...]  ← Mỗi switch cho 1 dãy phòng</span></span>
<span class="line"><span>  |        |</span></span>
<span class="line"><span>[PC phòng 1] [PC phòng 2]...</span></span></code></pre></div><ul><li>Địa chỉ IP được chia thành các <strong>subnet</strong> riêng: phòng lab (<code>192.168.10.x</code>), phòng giáo viên (<code>192.168.20.x</code>), thư viện (<code>192.168.30.x</code>).</li><li><strong>VLAN</strong> (mạng ảo) giúp tách biệt lưu lượng giữa các khu vực.</li></ul><hr><h2 id="🔹-6-so-sanh-phan-biet" tabindex="-1">🔹 6. SO SÁNH &amp; PHÂN BIỆT <a class="header-anchor" href="#🔹-6-so-sanh-phan-biet" aria-label="Permalink to &quot;🔹 6. SO SÁNH &amp; PHÂN BIỆT&quot;">​</a></h2><h3 id="switch-vs-router" tabindex="-1">Switch vs Router <a class="header-anchor" href="#switch-vs-router" aria-label="Permalink to &quot;Switch vs Router&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Switch</th><th>Router</th></tr></thead><tbody><tr><td><strong>Chức năng chính</strong></td><td>Kết nối thiết bị trong LAN</td><td>Kết nối các mạng khác nhau</td></tr><tr><td><strong>Địa chỉ sử dụng</strong></td><td>Địa chỉ MAC</td><td>Địa chỉ IP</td></tr><tr><td><strong>Tầng OSI</strong></td><td>Tầng 2 (Data Link)</td><td>Tầng 3 (Network)</td></tr><tr><td><strong>Phạm vi hoạt động</strong></td><td>Chỉ trong LAN</td><td>LAN ↔ WAN (Internet)</td></tr><tr><td><strong>Có DHCP không?</strong></td><td>Không</td><td>Có</td></tr><tr><td><strong>Ví dụ dùng ở đâu</strong></td><td>Kết nối máy tính trong văn phòng</td><td>Cổng vào Internet ở nhà</td></tr></tbody></table><h3 id="router-vs-modem" tabindex="-1">Router vs Modem <a class="header-anchor" href="#router-vs-modem" aria-label="Permalink to &quot;Router vs Modem&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>Router</th><th>Modem</th></tr></thead><tbody><tr><td><strong>Chức năng</strong></td><td>Phân phối và định tuyến mạng</td><td>Chuyển đổi tín hiệu</td></tr><tr><td><strong>Kết nối với ai</strong></td><td>Kết nối LAN và ISP</td><td>Kết nối trực tiếp với ISP</td></tr><tr><td><strong>Địa chỉ IP</strong></td><td>Quản lý IP nội bộ</td><td>Nhận IP công cộng từ ISP</td></tr><tr><td><strong>Tường lửa</strong></td><td>Có</td><td>Không</td></tr><tr><td><strong>Thiếu cái này thì sao?</strong></td><td>Mạng không phân phối được</td><td>Không kết nối được với ISP</td></tr></tbody></table><h3 id="đia-chi-mac-vs-đia-chi-ip" tabindex="-1">Địa chỉ MAC vs Địa chỉ IP <a class="header-anchor" href="#đia-chi-mac-vs-đia-chi-ip" aria-label="Permalink to &quot;Địa chỉ MAC vs Địa chỉ IP&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Tiêu chí</th><th>MAC Address</th><th>IP Address</th></tr></thead><tbody><tr><td><strong>Loại địa chỉ</strong></td><td>Vật lý (gắn với phần cứng)</td><td>Logic (có thể thay đổi)</td></tr><tr><td><strong>Cố định?</strong></td><td>Có (do nhà sản xuất gán)</td><td>Không (cấp bởi DHCP hoặc cấu hình tay)</td></tr><tr><td><strong>Dùng ở tầng nào</strong></td><td>Tầng 2</td><td>Tầng 3</td></tr><tr><td><strong>Phạm vi</strong></td><td>Chỉ trong LAN</td><td>Cả LAN lẫn Internet</td></tr><tr><td><strong>Ví dụ</strong></td><td><code>A4:C3:F0:85:AC:5D</code></td><td><code>192.168.1.10</code></td></tr><tr><td><strong>Thiết bị nào dùng</strong></td><td>Switch</td><td>Router</td></tr></tbody></table><hr><h2 id="🔹-7-ghi-nho-nhanh-đi-thi" tabindex="-1">🔹 7. GHI NHỚ NHANH (ĐI THI) <a class="header-anchor" href="#🔹-7-ghi-nho-nhanh-đi-thi" aria-label="Permalink to &quot;🔹 7. GHI NHỚ NHANH (ĐI THI)&quot;">​</a></h2><ul><li>🔵 <strong>Switch</strong> = kết nối <strong>trong LAN</strong> + dùng <strong>MAC</strong> address</li><li>🟢 <strong>Router</strong> = kết nối <strong>giữa các mạng</strong> + dùng <strong>IP</strong> address</li><li>🟡 <strong>Modem</strong> = chuyển đổi tín hiệu <strong>số ↔ analog</strong> để kết nối ISP</li><li>🔴 <strong>Access Point</strong> = phát <strong>Wi-Fi</strong>, cầu nối mạng có dây – không dây</li><li>📍 <strong>MAC</strong> = địa chỉ <strong>vật lý</strong>, <strong>cố định</strong>, dạng <code>XX:XX:XX:XX:XX:XX</code> (48 bit, hex)</li><li>📍 <strong>IP</strong> = địa chỉ <strong>logic</strong>, <strong>có thể thay đổi</strong>, dạng <code>X.X.X.X</code> (IPv4, 32 bit)</li><li>🔁 <strong>Luồng chuẩn:</strong> Internet → <strong>Modem</strong> → <strong>Router</strong> → <strong>Switch</strong> → Thiết bị</li><li>⚡ Switch dùng <strong>MAC table</strong> để chuyển frame đúng cổng (không phát tán)</li><li>⚡ Router dùng <strong>routing table</strong> để chuyển gói đúng mạng</li><li>🏠 Router thường <strong>tích hợp</strong> Switch + Access Point trong thiết bị gia đình</li></ul><hr><h2 id="🔹-8-bai-tap-tu-luyen" tabindex="-1">🔹 8. BÀI TẬP TỰ LUYỆN <a class="header-anchor" href="#🔹-8-bai-tap-tu-luyen" aria-label="Permalink to &quot;🔹 8. BÀI TẬP TỰ LUYỆN&quot;">​</a></h2><h3 id="cau-1-de-đien-vao-cho-trong" tabindex="-1">Câu 1 (Dễ): Điền vào chỗ trống <a class="header-anchor" href="#cau-1-de-đien-vao-cho-trong" aria-label="Permalink to &quot;Câu 1 (Dễ): Điền vào chỗ trống&quot;">​</a></h3><blockquote><p>Switch sử dụng địa chỉ _______ để chuyển dữ liệu, trong khi Router sử dụng địa chỉ _______.</p></blockquote><p><strong>Đáp án:</strong> Switch dùng <strong>MAC</strong>, Router dùng <strong>IP</strong>.</p><p><strong>Giải thích:</strong> Switch hoạt động ở tầng 2, chỉ quan tâm đến định danh vật lý (MAC) trong mạng nội bộ. Router hoạt động ở tầng 3, dùng IP để định tuyến giữa các mạng.</p><hr><h3 id="cau-2-de-trac-nghiem" tabindex="-1">Câu 2 (Dễ): Trắc nghiệm <a class="header-anchor" href="#cau-2-de-trac-nghiem" aria-label="Permalink to &quot;Câu 2 (Dễ): Trắc nghiệm&quot;">​</a></h3><blockquote><p>Thiết bị nào có chức năng chuyển đổi tín hiệu số thành tín hiệu analog để truyền qua đường dây điện thoại? A. Switch B. Router C. Modem D. Access Point</p></blockquote><p><strong>Đáp án: C – Modem</strong></p><p><strong>Giải thích:</strong> Modem (Modulator-Demodulator) thực hiện điều chế (modulate) và giải điều chế (demodulate) tín hiệu. Đây là thiết bị duy nhất trong danh sách có chức năng chuyển đổi tín hiệu giữa hai định dạng khác nhau.</p><hr><h3 id="cau-3-trung-binh-phan-tich-tinh-huong" tabindex="-1">Câu 3 (Trung bình): Phân tích tình huống <a class="header-anchor" href="#cau-3-trung-binh-phan-tich-tinh-huong" aria-label="Permalink to &quot;Câu 3 (Trung bình): Phân tích tình huống&quot;">​</a></h3><blockquote><p>Nhà bạn có router Wi-Fi nhưng tốc độ mạng rất chậm khi nhiều thiết bị dùng cùng lúc. Bạn muốn mua thêm thiết bị để kết nối 10 máy tính bàn bằng dây mà không ảnh hưởng đến Wi-Fi. Bạn nên mua thiết bị gì?</p></blockquote><p><strong>Đáp án:</strong> Mua thêm <strong>Switch</strong>.</p><p><strong>Giải thích:</strong> Switch giúp mở rộng số lượng cổng kết nối có dây trong LAN mà không tiêu thụ băng thông Wi-Fi. Nó cắm vào một cổng LAN của router và cung cấp thêm nhiều cổng cho máy tính bàn kết nối bằng cáp Ethernet – nhanh hơn và ổn định hơn Wi-Fi.</p><hr><h3 id="cau-4-trung-binh-sap-xep-luong-du-lieu" tabindex="-1">Câu 4 (Trung bình): Sắp xếp luồng dữ liệu <a class="header-anchor" href="#cau-4-trung-binh-sap-xep-luong-du-lieu" aria-label="Permalink to &quot;Câu 4 (Trung bình): Sắp xếp luồng dữ liệu&quot;">​</a></h3><blockquote><p>Sắp xếp theo đúng thứ tự luồng dữ liệu từ Internet đến máy tính: [Router] – [Thiết bị đầu cuối] – [Modem] – [Switch] – [Internet/ISP]</p></blockquote><p><strong>Đáp án:</strong> Internet/ISP → Modem → Router → Switch → Thiết bị đầu cuối</p><p><strong>Giải thích:</strong></p><ul><li>ISP truyền tín hiệu đến <strong>Modem</strong> (chuyển đổi tín hiệu).</li><li>Modem kết nối với <strong>Router</strong> (định tuyến và phân phối IP).</li><li>Router chuyển vào mạng nội bộ qua <strong>Switch</strong> (phân phát theo MAC).</li><li>Switch đưa dữ liệu đến đúng <strong>Thiết bị đầu cuối</strong>.</li></ul><hr><h3 id="cau-5-van-dung-thiet-ke-mang" tabindex="-1">Câu 5 (Vận dụng): Thiết kế mạng <a class="header-anchor" href="#cau-5-van-dung-thiet-ke-mang" aria-label="Permalink to &quot;Câu 5 (Vận dụng): Thiết kế mạng&quot;">​</a></h3><blockquote><p>Bạn được giao thiết kế mạng cho một văn phòng nhỏ gồm: 1 đường truyền cáp quang từ ISP, 20 máy tính bàn kết nối dây, 15 laptop kết nối Wi-Fi. Hãy liệt kê các thiết bị cần mua và giải thích vai trò của từng thiết bị.</p></blockquote><p><strong>Đáp án gợi ý:</strong></p><table tabindex="0"><thead><tr><th>Thiết bị</th><th>Số lượng</th><th>Vai trò</th></tr></thead><tbody><tr><td>Modem quang</td><td>1</td><td>Kết nối đường truyền ISP, chuyển đổi tín hiệu quang</td></tr><tr><td>Router</td><td>1</td><td>Phân phối mạng, cấp IP (DHCP), tường lửa, NAT</td></tr><tr><td>Switch 24 cổng</td><td>1</td><td>Kết nối 20 máy tính bàn bằng dây</td></tr><tr><td>Access Point</td><td>2-3</td><td>Phủ sóng Wi-Fi cho 15 laptop (tùy diện tích văn phòng)</td></tr></tbody></table><p><strong>Giải thích:</strong> Modem kết nối ISP → Router quản lý toàn mạng → Switch mở rộng cổng có dây → AP phủ sóng không dây. Dùng 2-3 AP để tránh nghẽn khi 15 laptop dùng cùng lúc.</p><hr><h2 id="🔹-9-loi-thuong-gap" tabindex="-1">🔹 9. LỖI THƯỜNG GẶP <a class="header-anchor" href="#🔹-9-loi-thuong-gap" aria-label="Permalink to &quot;🔹 9. LỖI THƯỜNG GẶP&quot;">​</a></h2><h3 id="❌-loi-1-nham-switch-voi-hub" tabindex="-1">❌ Lỗi 1: Nhầm Switch với Hub <a class="header-anchor" href="#❌-loi-1-nham-switch-voi-hub" aria-label="Permalink to &quot;❌ Lỗi 1: Nhầm Switch với Hub&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch phát tán dữ liệu đến tất cả thiết bị trong mạng.&quot;</p><p><strong>Đúng:</strong> Switch <strong>chỉ gửi đến đúng thiết bị đích</strong> bằng cách tra bảng MAC. Hub mới phát tán (broadcast) đến tất cả – nhưng Hub gần như không còn được dùng ngày nay.</p><hr><h3 id="❌-loi-2-nham-router-voi-modem" tabindex="-1">❌ Lỗi 2: Nhầm Router với Modem <a class="header-anchor" href="#❌-loi-2-nham-router-voi-modem" aria-label="Permalink to &quot;❌ Lỗi 2: Nhầm Router với Modem&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Modem kết nối các máy tính trong nhà với nhau.&quot;</p><p><strong>Đúng:</strong> Modem chỉ làm nhiệm vụ <strong>chuyển đổi tín hiệu</strong> giữa ISP và mạng nhà. Chính <strong>Router</strong> mới là thiết bị kết nối và phân phối mạng nội bộ. (Lưu ý: nhiều thiết bị gia đình tích hợp cả hai trong một hộp, dễ nhầm lẫn.)</p><hr><h3 id="❌-loi-3-nghi-đia-chi-mac-co-the-dung-đe-đinh-tuyen-tren-internet" tabindex="-1">❌ Lỗi 3: Nghĩ địa chỉ MAC có thể dùng để định tuyến trên Internet <a class="header-anchor" href="#❌-loi-3-nghi-đia-chi-mac-co-the-dung-đe-đinh-tuyen-tren-internet" aria-label="Permalink to &quot;❌ Lỗi 3: Nghĩ địa chỉ MAC có thể dùng để định tuyến trên Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Router dùng địa chỉ MAC để gửi dữ liệu qua Internet.&quot;</p><p><strong>Đúng:</strong> MAC address <strong>chỉ có giá trị trong phạm vi LAN</strong>. Khi dữ liệu ra khỏi mạng nội bộ, Router dùng <strong>địa chỉ IP</strong> để định tuyến. MAC không bao giờ &quot;đi&quot; ra ngoài Internet.</p><hr><h3 id="❌-loi-4-nghi-ip-noi-bo-la-duy-nhat-toan-cau" tabindex="-1">❌ Lỗi 4: Nghĩ IP nội bộ là duy nhất toàn cầu <a class="header-anchor" href="#❌-loi-4-nghi-ip-noi-bo-la-duy-nhat-toan-cau" aria-label="Permalink to &quot;❌ Lỗi 4: Nghĩ IP nội bộ là duy nhất toàn cầu&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ 192.168.1.1 của router nhà tôi là duy nhất trên thế giới.&quot;</p><p><strong>Đúng:</strong> <code>192.168.x.x</code> là <strong>dải IP riêng tư (private IP)</strong>, có thể trùng ở hàng triệu nhà trên thế giới. Chỉ có <strong>IP công cộng (public IP)</strong> do ISP cấp mới là duy nhất. Tính duy nhất trong LAN là đủ, nhờ NAT của router.</p><hr><h3 id="❌-loi-5-nham-access-point-voi-router" tabindex="-1">❌ Lỗi 5: Nhầm Access Point với Router <a class="header-anchor" href="#❌-loi-5-nham-access-point-voi-router" aria-label="Permalink to &quot;❌ Lỗi 5: Nhầm Access Point với Router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Access Point có thể thay thế hoàn toàn Router.&quot;</p><p><strong>Đúng:</strong> Access Point <strong>chỉ phát sóng Wi-Fi</strong> – không có khả năng định tuyến, NAT hay cấp IP (DHCP). Nếu không có Router phía sau, AP không thể kết nối Internet. Access Point chỉ là &quot;cây cầu không dây&quot;, Router mới là &quot;bộ não&quot; của mạng.</p><hr><h3 id="❌-loi-6-nghi-router-gia-đinh-va-router-doanh-nghiep-la-nhu-nhau" tabindex="-1">❌ Lỗi 6: Nghĩ Router gia đình và Router doanh nghiệp là như nhau <a class="header-anchor" href="#❌-loi-6-nghi-router-gia-đinh-va-router-doanh-nghiep-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 6: Nghĩ Router gia đình và Router doanh nghiệp là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Router Wi-Fi nhà tôi có thể dùng cho văn phòng 200 nhân viên.&quot;</p><p><strong>Đúng:</strong> Router gia đình được thiết kế cho ~10–30 thiết bị. Router doanh nghiệp hỗ trợ hàng trăm kết nối đồng thời, có tính năng VLAN, QoS, routing nâng cao. Dùng sai thiết bị gây nghẽn mạng nghiêm trọng.</p><hr><h3 id="❌-loi-7-nham-bang-thong-bandwidth-voi-toc-đo-speed" tabindex="-1">❌ Lỗi 7: Nhầm băng thông (bandwidth) với tốc độ (speed) <a class="header-anchor" href="#❌-loi-7-nham-bang-thong-bandwidth-voi-toc-đo-speed" aria-label="Permalink to &quot;❌ Lỗi 7: Nhầm băng thông (bandwidth) với tốc độ (speed)&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Băng thông 1 Gbps nghĩa là file 1 GB tải xong trong 1 giây.&quot;</p><p><strong>Đúng:</strong> Băng thông là dung lượng tối đa của đường truyền. Tốc độ thực tế phụ thuộc vào nhiều yếu tố: độ trễ, tình trạng mạng, phần cứng. 1 Gbps = 1.000 Mbps = ~125 MB/s lý thuyết, thực tế thường thấp hơn nhiều.</p><hr><h3 id="❌-loi-8-nghi-wi-fi-5ghz-luon-tot-hon-2-4ghz" tabindex="-1">❌ Lỗi 8: Nghĩ Wi-Fi 5GHz luôn tốt hơn 2.4GHz <a class="header-anchor" href="#❌-loi-8-nghi-wi-fi-5ghz-luon-tot-hon-2-4ghz" aria-label="Permalink to &quot;❌ Lỗi 8: Nghĩ Wi-Fi 5GHz luôn tốt hơn 2.4GHz&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Nên dùng Wi-Fi 5GHz vì nhanh hơn, luôn luôn.&quot;</p><p><strong>Đúng:</strong> 5GHz nhanh hơn nhưng <strong>phạm vi ngắn hơn và kém xuyên tường hơn</strong> 2.4GHz. Ở gần router thì dùng 5GHz. Ở xa hoặc qua nhiều tường thì 2.4GHz ổn định hơn.</p><hr><h3 id="❌-loi-9-cho-rang-cap-ethernet-loai-nao-cung-nhu-nhau" tabindex="-1">❌ Lỗi 9: Cho rằng cáp Ethernet loại nào cũng như nhau <a class="header-anchor" href="#❌-loi-9-cho-rang-cap-ethernet-loai-nao-cung-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 9: Cho rằng cáp Ethernet loại nào cũng như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cắm dây mạng vào là kết nối tốt, dây nào cũng được.&quot;</p><p><strong>Đúng:</strong> Cáp Cat5e hỗ trợ tối đa 1 Gbps/100m. Cat6 hỗ trợ 10 Gbps/55m. Cat7 giảm nhiễu tốt hơn. Dùng cáp cũ (Cat3/Cat5 thẳng) sẽ giới hạn tốc độ dù switch và NIC hỗ trợ tốc độ cao hơn.</p><hr><h3 id="❌-loi-10-nham-nic-voi-card-đo-hoa" tabindex="-1">❌ Lỗi 10: Nhầm NIC với Card đồ họa <a class="header-anchor" href="#❌-loi-10-nham-nic-voi-card-đo-hoa" aria-label="Permalink to &quot;❌ Lỗi 10: Nhầm NIC với Card đồ họa&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Card mạng và card màn hình đều là card, nên giống nhau.&quot;</p><p><strong>Đúng:</strong> <strong>NIC (Network Interface Card)</strong> là phần cứng kết nối máy tính vào mạng, dùng địa chỉ MAC. Card đồ họa (GPU) xử lý hình ảnh. Hai thiết bị hoàn toàn khác nhau về chức năng.</p><hr><h3 id="❌-loi-11-nghi-đia-chi-mac-khong-the-gia-mao" tabindex="-1">❌ Lỗi 11: Nghĩ địa chỉ MAC không thể giả mạo <a class="header-anchor" href="#❌-loi-11-nghi-đia-chi-mac-khong-the-gia-mao" aria-label="Permalink to &quot;❌ Lỗi 11: Nghĩ địa chỉ MAC không thể giả mạo&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ MAC gắn cứng với phần cứng, không thể thay đổi.&quot;</p><p><strong>Đúng:</strong> Mặc dù MAC được nhà sản xuất gán vào phần cứng, phần mềm hệ điều hành <strong>cho phép &quot;giả mạo&quot; (MAC spoofing)</strong> – thay đổi MAC hiển thị ra mạng. Đây là kỹ thuật dùng cho cả bảo mật (riêng tư) và tấn công.</p><hr><h3 id="❌-loi-12-nham-default-gateway-voi-dns-server" tabindex="-1">❌ Lỗi 12: Nhầm Default Gateway với DNS Server <a class="header-anchor" href="#❌-loi-12-nham-default-gateway-voi-dns-server" aria-label="Permalink to &quot;❌ Lỗi 12: Nhầm Default Gateway với DNS Server&quot;">​</a></h3><p><strong>Sai:</strong> &quot;192.168.1.1 là DNS server của tôi.&quot;</p><p><strong>Đúng:</strong> <code>192.168.1.1</code> thường là <strong>Default Gateway</strong> (địa chỉ Router) – nơi gói tin đi ra khỏi LAN. <strong>DNS Server</strong> (ví dụ: <code>8.8.8.8</code> của Google) mới là nơi dịch tên miền sang IP. Một số router tích hợp DNS caching, dễ nhầm.</p><hr><h3 id="❌-loi-13-nghi-dhcp-chi-co-o-router-gia-đinh" tabindex="-1">❌ Lỗi 13: Nghĩ DHCP chỉ có ở router gia đình <a class="header-anchor" href="#❌-loi-13-nghi-dhcp-chi-co-o-router-gia-đinh" aria-label="Permalink to &quot;❌ Lỗi 13: Nghĩ DHCP chỉ có ở router gia đình&quot;">​</a></h3><p><strong>Sai:</strong> &quot;DHCP là tính năng của router Wi-Fi nhà, doanh nghiệp không dùng.&quot;</p><p><strong>Đúng:</strong> DHCP (Dynamic Host Configuration Protocol) được dùng rộng rãi cả trong mạng doanh nghiệp. Trong môi trường lớn, DHCP thường chạy trên <strong>server riêng</strong> chứ không phải trên router. DHCP cấp IP, subnet mask, default gateway, và DNS tự động.</p><hr><h3 id="❌-loi-14-nham-ping-voi-toc-đo-internet" tabindex="-1">❌ Lỗi 14: Nhầm Ping với tốc độ Internet <a class="header-anchor" href="#❌-loi-14-nham-ping-voi-toc-đo-internet" aria-label="Permalink to &quot;❌ Lỗi 14: Nhầm Ping với tốc độ Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Ping thấp nghĩa là Internet nhanh.&quot;</p><p><strong>Đúng:</strong> <strong>Ping (độ trễ/latency)</strong> đo thời gian gói tin đi từ máy bạn đến đích và quay lại (đơn vị ms). <strong>Tốc độ (bandwidth)</strong> đo lượng dữ liệu truyền được mỗi giây (Mbps). Ping thấp tốt cho game/video call, tốc độ cao tốt cho tải file. Hai chỉ số độc lập với nhau.</p><hr><h3 id="❌-loi-15-nghi-poe-la-cong-nghe-wi-fi-đac-biet" tabindex="-1">❌ Lỗi 15: Nghĩ PoE là công nghệ Wi-Fi đặc biệt <a class="header-anchor" href="#❌-loi-15-nghi-poe-la-cong-nghe-wi-fi-đac-biet" aria-label="Permalink to &quot;❌ Lỗi 15: Nghĩ PoE là công nghệ Wi-Fi đặc biệt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;PoE là chuẩn Wi-Fi mới hơn Wi-Fi 6.&quot;</p><p><strong>Đúng:</strong> <strong>PoE (Power over Ethernet)</strong> là công nghệ <strong>cấp điện qua cáp mạng</strong>. Thiết bị như Access Point, camera IP, điện thoại VoIP dùng PoE để nhận điện từ switch thay vì cần ổ cắm điện riêng. PoE không liên quan đến chuẩn Wi-Fi.</p><hr><h3 id="❌-loi-16-nham-full-duplex-voi-half-duplex" tabindex="-1">❌ Lỗi 16: Nhầm Full-Duplex với Half-Duplex <a class="header-anchor" href="#❌-loi-16-nham-full-duplex-voi-half-duplex" aria-label="Permalink to &quot;❌ Lỗi 16: Nhầm Full-Duplex với Half-Duplex&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Kết nối mạng luôn là two-way, không cần phân biệt.&quot;</p><p><strong>Đúng:</strong> <strong>Half-duplex</strong> truyền dữ liệu <strong>một chiều tại một thời điểm</strong> (giống bộ đàm). <strong>Full-duplex</strong> truyền <strong>hai chiều đồng thời</strong> (giống điện thoại). Switch hiện đại hỗ trợ full-duplex – tốc độ hiệu quả gấp đôi half-duplex.</p><hr><h3 id="❌-loi-17-nghi-loopback-address-la-đia-chi-cua-router" tabindex="-1">❌ Lỗi 17: Nghĩ loopback address là địa chỉ của router <a class="header-anchor" href="#❌-loi-17-nghi-loopback-address-la-đia-chi-cua-router" aria-label="Permalink to &quot;❌ Lỗi 17: Nghĩ loopback address là địa chỉ của router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ 127.0.0.1 là IP của router nhà tôi.&quot;</p><p><strong>Đúng:</strong> <code>127.0.0.1</code> là <strong>loopback address</strong> – địa chỉ đặc biệt chỉ về <strong>chính máy tính đang dùng</strong> (localhost). Dùng để kiểm tra hoạt động mạng nội bộ máy. Khi ping <code>127.0.0.1</code> thành công, chứng tỏ card mạng và TCP/IP stack trên máy hoạt động bình thường.</p><hr><h3 id="❌-loi-18-nham-wan-port-voi-lan-port-tren-router" tabindex="-1">❌ Lỗi 18: Nhầm WAN port với LAN port trên Router <a class="header-anchor" href="#❌-loi-18-nham-wan-port-voi-lan-port-tren-router" aria-label="Permalink to &quot;❌ Lỗi 18: Nhầm WAN port với LAN port trên Router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cắm cáp từ modem vào bất kỳ cổng nào của router đều được.&quot;</p><p><strong>Đúng:</strong> Router có <strong>1 cổng WAN</strong> (cổng uplink, kết nối với modem/ISP) và <strong>nhiều cổng LAN</strong> (kết nối thiết bị trong nhà). Cắm nhầm WAN/LAN sẽ khiến router không định tuyến được Internet.</p><hr><h3 id="❌-loi-19-nghi-subnet-mask-khong-quan-trong-o-mang-gia-đinh" tabindex="-1">❌ Lỗi 19: Nghĩ Subnet Mask không quan trọng ở mạng gia đình <a class="header-anchor" href="#❌-loi-19-nghi-subnet-mask-khong-quan-trong-o-mang-gia-đinh" aria-label="Permalink to &quot;❌ Lỗi 19: Nghĩ Subnet Mask không quan trọng ở mạng gia đình&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Subnet mask chỉ cần biết khi học, thực tế không cần thiết.&quot;</p><p><strong>Đúng:</strong> Subnet mask xác định phần nào của địa chỉ IP là <strong>địa chỉ mạng</strong> và phần nào là <strong>địa chỉ host</strong>. Cấu hình sai subnet mask (ví dụ: <code>/24</code> thay vì <code>/25</code>) có thể khiến hai thiết bị cùng mạng không giao tiếp được với nhau.</p><hr><h3 id="❌-loi-20-nghi-switch-managed-va-unmanaged-la-nhu-nhau" tabindex="-1">❌ Lỗi 20: Nghĩ Switch Managed và Unmanaged là như nhau <a class="header-anchor" href="#❌-loi-20-nghi-switch-managed-va-unmanaged-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 20: Nghĩ Switch Managed và Unmanaged là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch nào cũng như nhau, chỉ khác số lượng cổng.&quot;</p><p><strong>Đúng:</strong> <strong>Switch Unmanaged</strong> là plug-and-play, không cấu hình được. <strong>Switch Managed</strong> có thể cấu hình VLAN, QoS, Port mirroring, giám sát lưu lượng. Doanh nghiệp dùng Managed Switch để kiểm soát mạng chi tiết hơn.</p><hr><h3 id="❌-loi-21-nham-ipv6-chi-la-ipv4-dai-hon" tabindex="-1">❌ Lỗi 21: Nhầm IPv6 chỉ là &quot;IPv4 dài hơn&quot; <a class="header-anchor" href="#❌-loi-21-nham-ipv6-chi-la-ipv4-dai-hon" aria-label="Permalink to &quot;❌ Lỗi 21: Nhầm IPv6 chỉ là &quot;IPv4 dài hơn&quot;&quot;">​</a></h3><p><strong>Sai:</strong> &quot;IPv6 chỉ khác IPv4 ở chỗ địa chỉ dài hơn.&quot;</p><p><strong>Đúng:</strong> IPv6 (128-bit) không chỉ tăng không gian địa chỉ mà còn cải tiến: <strong>tích hợp bảo mật (IPSec)</strong>, không cần NAT, header đơn giản hơn, hỗ trợ multicast tốt hơn, auto-configuration (SLAAC). Đây là một thiết kế lại hoàn toàn.</p><hr><h3 id="❌-loi-22-nghi-ket-noi-day-luon-nhanh-hon-wi-fi" tabindex="-1">❌ Lỗi 22: Nghĩ kết nối dây luôn nhanh hơn Wi-Fi <a class="header-anchor" href="#❌-loi-22-nghi-ket-noi-day-luon-nhanh-hon-wi-fi" aria-label="Permalink to &quot;❌ Lỗi 22: Nghĩ kết nối dây luôn nhanh hơn Wi-Fi&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng dây mạng luôn nhanh hơn Wi-Fi bất kể hoàn cảnh.&quot;</p><p><strong>Đúng:</strong> Đúng về mặt lý thuyết, nhưng nếu cáp bị hỏng, connector lỏng, hoặc cổng switch bị lỗi thì kết nối dây còn kém Wi-Fi. Wi-Fi 6 (802.11ax) có thể đạt tốc độ 9.6 Gbps lý thuyết, nhanh hơn nhiều kết nối dây Gigabit thông thường.</p><hr><h3 id="❌-loi-23-nghi-port-forwarding-va-port-blocking-la-giong-nhau" tabindex="-1">❌ Lỗi 23: Nghĩ port forwarding và port blocking là giống nhau <a class="header-anchor" href="#❌-loi-23-nghi-port-forwarding-va-port-blocking-la-giong-nhau" aria-label="Permalink to &quot;❌ Lỗi 23: Nghĩ port forwarding và port blocking là giống nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Port forwarding là mở cổng, port blocking là đóng cổng, hai cái giống nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Port forwarding</strong> chuyển hướng kết nối từ ngoài Internet vào thiết bị cụ thể trong LAN (ví dụ: để chạy server game). <strong>Port blocking</strong> chặn hoàn toàn kết nối qua cổng đó. Đây là hai tính năng router hoàn toàn khác nhau.</p><hr><h3 id="❌-loi-24-nham-access-point-mode-va-router-mode" tabindex="-1">❌ Lỗi 24: Nhầm Access Point Mode và Router Mode <a class="header-anchor" href="#❌-loi-24-nham-access-point-mode-va-router-mode" aria-label="Permalink to &quot;❌ Lỗi 24: Nhầm Access Point Mode và Router Mode&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mua thiết bị Wi-Fi mới, cắm vào là dùng được ngay.&quot;</p><p><strong>Đúng:</strong> Thiết bị Wi-Fi có thể hoạt động ở nhiều chế độ: <strong>Router mode</strong> (hoạt động như router đầy đủ), <strong>Access Point mode</strong> (chỉ phát sóng, không có NAT/DHCP), <strong>Repeater mode</strong> (khuếch đại sóng). Cắm nhầm chế độ có thể gây conflict IP hoặc mạng không hoạt động.</p><hr><h3 id="❌-loi-25-nghi-firewall-chi-la-phan-mem" tabindex="-1">❌ Lỗi 25: Nghĩ Firewall chỉ là phần mềm <a class="header-anchor" href="#❌-loi-25-nghi-firewall-chi-la-phan-mem" aria-label="Permalink to &quot;❌ Lỗi 25: Nghĩ Firewall chỉ là phần mềm&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Firewall là phần mềm như Windows Defender.&quot;</p><p><strong>Đúng:</strong> Firewall có thể là <strong>phần mềm</strong> (Windows Firewall, iptables) hoặc <strong>phần cứng</strong> (thiết bị chuyên dụng Cisco ASA, Fortinet). Router gia đình cũng tích hợp tường lửa cơ bản (hardware firewall). Cả hai đều lọc lưu lượng mạng nhưng ở mức độ và vị trí khác nhau.</p><hr><h3 id="❌-loi-26-nghi-moi-thiet-bi-chi-co-mot-đia-chi-mac" tabindex="-1">❌ Lỗi 26: Nghĩ mỗi thiết bị chỉ có một địa chỉ MAC <a class="header-anchor" href="#❌-loi-26-nghi-moi-thiet-bi-chi-co-mot-đia-chi-mac" aria-label="Permalink to &quot;❌ Lỗi 26: Nghĩ mỗi thiết bị chỉ có một địa chỉ MAC&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Laptop của tôi có đúng một địa chỉ MAC.&quot;</p><p><strong>Đúng:</strong> Mỗi <strong>card mạng</strong> có một MAC. Laptop thường có <strong>hai card mạng</strong>: card Ethernet (dây) và card Wi-Fi (không dây) → hai địa chỉ MAC khác nhau. Thiết bị có cả Bluetooth, LTE thì có thêm.</p><hr><h3 id="❌-loi-27-nham-repeater-voi-access-point" tabindex="-1">❌ Lỗi 27: Nhầm Repeater với Access Point <a class="header-anchor" href="#❌-loi-27-nham-repeater-voi-access-point" aria-label="Permalink to &quot;❌ Lỗi 27: Nhầm Repeater với Access Point&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Repeater và Access Point đều phát Wi-Fi, như nhau.&quot;</p><p><strong>Đúng:</strong> <strong>Access Point</strong> kết nối trực tiếp bằng dây vào switch/router, cung cấp tín hiệu mạnh và ổn định. <strong>Repeater/Extender</strong> bắt sóng Wi-Fi có sẵn rồi phát lại, nhưng thường làm giảm băng thông 50% vì phải vừa nhận vừa phát trên cùng tần số.</p><hr><h3 id="❌-loi-28-nghi-tat-ca-đia-chi-ip-bat-đau-bang-192-168-la-router" tabindex="-1">❌ Lỗi 28: Nghĩ tất cả địa chỉ IP bắt đầu bằng 192.168 là router <a class="header-anchor" href="#❌-loi-28-nghi-tat-ca-đia-chi-ip-bat-đau-bang-192-168-la-router" aria-label="Permalink to &quot;❌ Lỗi 28: Nghĩ tất cả địa chỉ IP bắt đầu bằng 192.168 là router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Địa chỉ 192.168.x.x nào cũng là router.&quot;</p><p><strong>Đúng:</strong> <code>192.168.x.x</code> là <strong>dải địa chỉ riêng tư (private)</strong> dùng trong LAN. Router thường có địa chỉ <code>.1</code> (như <code>192.168.1.1</code>) nhưng không bắt buộc. Các thiết bị khác trong mạng cũng có địa chỉ <code>192.168.x.x</code> (như <code>192.168.1.2</code>, <code>192.168.1.10</code>...).</p><hr><h3 id="❌-loi-29-nham-arp-voi-dns" tabindex="-1">❌ Lỗi 29: Nhầm ARP với DNS <a class="header-anchor" href="#❌-loi-29-nham-arp-voi-dns" aria-label="Permalink to &quot;❌ Lỗi 29: Nhầm ARP với DNS&quot;">​</a></h3><p><strong>Sai:</strong> &quot;ARP dịch tên miền sang địa chỉ IP.&quot;</p><p><strong>Đúng:</strong> <strong>DNS (Domain Name System)</strong> dịch tên miền (như <code>google.com</code>) sang địa chỉ IP. <strong>ARP (Address Resolution Protocol)</strong> dịch địa chỉ IP sang địa chỉ MAC trong LAN. Hai giao thức phục vụ hai mục đích hoàn toàn khác nhau.</p><hr><h3 id="❌-loi-30-nghi-router-tat-nguon-thi-lan-van-hoat-đong" tabindex="-1">❌ Lỗi 30: Nghĩ router tắt nguồn thì LAN vẫn hoạt động <a class="header-anchor" href="#❌-loi-30-nghi-router-tat-nguon-thi-lan-van-hoat-đong" aria-label="Permalink to &quot;❌ Lỗi 30: Nghĩ router tắt nguồn thì LAN vẫn hoạt động&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Hai máy tính trong nhà vẫn nói chuyện được dù router tắt, vì chúng dùng switch.&quot;</p><p><strong>Đúng:</strong> Nếu hai máy nối qua <strong>switch</strong> (không qua router), chúng vẫn giao tiếp được trong LAN. Nhưng nếu nối <strong>qua router</strong> (router đóng vai switch), tắt router sẽ ngắt liên lạc. Cần hiểu sơ đồ mạng cụ thể của từng hệ thống.</p><hr><h3 id="❌-loi-31-nghi-ssid-la-mat-khau-wi-fi" tabindex="-1">❌ Lỗi 31: Nghĩ SSID là mật khẩu Wi-Fi <a class="header-anchor" href="#❌-loi-31-nghi-ssid-la-mat-khau-wi-fi" aria-label="Permalink to &quot;❌ Lỗi 31: Nghĩ SSID là mật khẩu Wi-Fi&quot;">​</a></h3><p><strong>Sai:</strong> &quot;SSID là mật khẩu để kết nối Wi-Fi.&quot;</p><p><strong>Đúng:</strong> <strong>SSID (Service Set Identifier)</strong> là <strong>tên mạng Wi-Fi</strong> (tên hiển thị khi bạn tìm Wi-Fi). Mật khẩu Wi-Fi là <strong>Pre-Shared Key (PSK)</strong> hoặc <strong>WPA/WPA2 password</strong>. SSID có thể ẩn đi (hidden SSID) nhưng mạng vẫn hoạt động.</p><hr><h3 id="❌-loi-32-nham-toc-đo-cong-switch-voi-toc-đo-internet" tabindex="-1">❌ Lỗi 32: Nhầm tốc độ cổng Switch với tốc độ Internet <a class="header-anchor" href="#❌-loi-32-nham-toc-đo-cong-switch-voi-toc-đo-internet" aria-label="Permalink to &quot;❌ Lỗi 32: Nhầm tốc độ cổng Switch với tốc độ Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Switch Gigabit nghĩa là Internet nhà tôi đạt 1 Gbps.&quot;</p><p><strong>Đúng:</strong> Switch Gigabit chỉ có nghĩa là <strong>kết nối trong LAN</strong> đạt 1 Gbps. Tốc độ Internet phụ thuộc vào gói cước từ ISP (thường 100 Mbps, 200 Mbps...). Switch chỉ liên quan đến tốc độ nội bộ, không ảnh hưởng đến tốc độ từ ISP.</p><hr><h3 id="❌-loi-33-nghi-vpn-thay-the-router" tabindex="-1">❌ Lỗi 33: Nghĩ VPN thay thế Router <a class="header-anchor" href="#❌-loi-33-nghi-vpn-thay-the-router" aria-label="Permalink to &quot;❌ Lỗi 33: Nghĩ VPN thay thế Router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng VPN thì không cần router nữa.&quot;</p><p><strong>Đúng:</strong> VPN (Virtual Private Network) là <strong>phần mềm tạo đường hầm mã hóa</strong> để che giấu lưu lượng Internet. Router vẫn cần thiết để kết nối các thiết bị và quản lý mạng nội bộ. VPN là một lớp bảo mật phủ lên kết nối Internet, không thay thế thiết bị mạng vật lý.</p><hr><h3 id="❌-loi-34-nham-mbps-voi-mbps" tabindex="-1">❌ Lỗi 34: Nhầm Mbps với MBps <a class="header-anchor" href="#❌-loi-34-nham-mbps-voi-mbps" aria-label="Permalink to &quot;❌ Lỗi 34: Nhầm Mbps với MBps&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tốc độ 100 Mbps nghĩa là tải được 100 MB mỗi giây.&quot;</p><p><strong>Đúng:</strong> <strong>Mbps</strong> = Megabit per second, <strong>MBps</strong> = Megabyte per second. 1 Byte = 8 bit, nên 100 Mbps ≈ 12.5 MBps. Nhà mạng thường quảng cáo tốc độ theo Mbps, nhưng trình duyệt/phần mềm tải file thường hiển thị theo MB/s – dễ gây hiểu nhầm.</p><hr><h3 id="❌-loi-35-nghi-đia-chi-ip-va-hostname-la-giong-nhau" tabindex="-1">❌ Lỗi 35: Nghĩ địa chỉ IP và hostname là giống nhau <a class="header-anchor" href="#❌-loi-35-nghi-đia-chi-ip-va-hostname-la-giong-nhau" aria-label="Permalink to &quot;❌ Lỗi 35: Nghĩ địa chỉ IP và hostname là giống nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tên máy tính và địa chỉ IP là một.&quot;</p><p><strong>Đúng:</strong> <strong>Hostname</strong> (tên máy, như <code>LAPTOP-ABC</code>) là tên định danh trong mạng nội bộ. <strong>Địa chỉ IP</strong> là địa chỉ số dùng để định tuyến. Hostname được dịch sang IP bởi DNS (hoặc file hosts). Một hostname có thể ứng với nhiều IP (load balancing) và một IP có thể có nhiều hostname.</p><hr><h3 id="❌-loi-36-nham-wireless-router-voi-access-point-thuan-tuy" tabindex="-1">❌ Lỗi 36: Nhầm Wireless Router với Access Point thuần túy <a class="header-anchor" href="#❌-loi-36-nham-wireless-router-voi-access-point-thuan-tuy" aria-label="Permalink to &quot;❌ Lỗi 36: Nhầm Wireless Router với Access Point thuần túy&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Cái hộp Wi-Fi ở nhà tôi chỉ phát sóng Wi-Fi thôi.&quot;</p><p><strong>Đúng:</strong> Thiết bị Wi-Fi gia đình thường là <strong>Wireless Router tích hợp</strong> – bao gồm: Modem (nếu là ADSL/VDSL combo), Router, Switch 4 cổng, và Access Point, tất cả trong một hộp. Đây là lý do tại sao tắt thiết bị đó thì cả dây lẫn Wi-Fi đều ngắt.</p><hr><h3 id="❌-loi-37-nghi-tan-so-va-kenh-wi-fi-la-nhu-nhau" tabindex="-1">❌ Lỗi 37: Nghĩ tần số và kênh Wi-Fi là như nhau <a class="header-anchor" href="#❌-loi-37-nghi-tan-so-va-kenh-wi-fi-la-nhu-nhau" aria-label="Permalink to &quot;❌ Lỗi 37: Nghĩ tần số và kênh Wi-Fi là như nhau&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Wi-Fi 2.4GHz và kênh 6 là hai điều khác nhau hoàn toàn.&quot;</p><p><strong>Đúng:</strong> <strong>Tần số</strong> (2.4GHz, 5GHz) là dải sóng rộng. <strong>Kênh (channel)</strong> là phân vùng nhỏ hơn trong tần số đó. Băng 2.4GHz có 13 kênh (1–13), nhưng chỉ có 3 kênh không chồng lấp (1, 6, 11). Dùng cùng kênh với hàng xóm gây nhiễu, giảm tốc độ.</p><hr><h3 id="❌-loi-38-nghi-đia-chi-0-0-0-0-la-hop-le-cho-thiet-bi" tabindex="-1">❌ Lỗi 38: Nghĩ địa chỉ 0.0.0.0 là hợp lệ cho thiết bị <a class="header-anchor" href="#❌-loi-38-nghi-đia-chi-0-0-0-0-la-hop-le-cho-thiet-bi" aria-label="Permalink to &quot;❌ Lỗi 38: Nghĩ địa chỉ 0.0.0.0 là hợp lệ cho thiết bị&quot;">​</a></h3><p><strong>Sai:</strong> &quot;0.0.0.0 là địa chỉ IP hợp lệ có thể cấp cho máy tính.&quot;</p><p><strong>Đúng:</strong> <code>0.0.0.0</code> là địa chỉ đặc biệt, dùng trong cấu hình routing để chỉ <strong>bất kỳ địa chỉ nào</strong> (trong lệnh default route <code>0.0.0.0/0</code>). Không thể gán địa chỉ này cho thiết bị thực. Tương tự, <code>255.255.255.255</code> là địa chỉ broadcast toàn mạng.</p><hr><h3 id="❌-loi-39-nham-vlan-voi-vpn" tabindex="-1">❌ Lỗi 39: Nhầm VLAN với VPN <a class="header-anchor" href="#❌-loi-39-nham-vlan-voi-vpn" aria-label="Permalink to &quot;❌ Lỗi 39: Nhầm VLAN với VPN&quot;">​</a></h3><p><strong>Sai:</strong> &quot;VLAN là mạng ảo riêng tư trên Internet như VPN.&quot;</p><p><strong>Đúng:</strong> <strong>VLAN (Virtual LAN)</strong> phân chia switch vật lý thành nhiều mạng logic riêng biệt trong nội bộ – để tách biệt phòng ban mà không cần thêm switch vật lý. <strong>VPN</strong> là kết nối bảo mật qua Internet. Hai công nghệ hoàn toàn khác nhau về mục đích và cách hoạt động.</p><hr><h3 id="❌-loi-40-nghi-router-tu-đong-bao-ve-khoi-tan-cong" tabindex="-1">❌ Lỗi 40: Nghĩ router tự động bảo vệ khỏi tấn công <a class="header-anchor" href="#❌-loi-40-nghi-router-tu-đong-bao-ve-khoi-tan-cong" aria-label="Permalink to &quot;❌ Lỗi 40: Nghĩ router tự động bảo vệ khỏi tấn công&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Có router rồi thì mạng tự động an toàn.&quot;</p><p><strong>Đúng:</strong> Router mặc định chỉ có <strong>NAT và firewall cơ bản</strong>. Không tự động chặn malware, phishing, tấn công brute-force vào các dịch vụ bên trong. Cần thêm: cập nhật firmware, đổi mật khẩu admin router, tắt remote management, dùng WPA3, và cấu hình firewall đúng cách.</p><hr><h3 id="❌-loi-41-nghi-mat-khau-wi-fi-la-mat-khau-quan-tri-router" tabindex="-1">❌ Lỗi 41: Nghĩ mật khẩu Wi-Fi là mật khẩu quản trị router <a class="header-anchor" href="#❌-loi-41-nghi-mat-khau-wi-fi-la-mat-khau-quan-tri-router" aria-label="Permalink to &quot;❌ Lỗi 41: Nghĩ mật khẩu Wi-Fi là mật khẩu quản trị router&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mật khẩu Wi-Fi và mật khẩu đăng nhập vào trang quản trị router (admin) là một.&quot;</p><p><strong>Đúng:</strong> Đây là <strong>hai mật khẩu riêng biệt</strong>. Mật khẩu Wi-Fi (WPA/WPA2) để kết nối vào mạng không dây. Mật khẩu admin (thường là <code>admin/admin</code> mặc định) để vào trang quản trị router. Cần đổi cả hai, đặc biệt là mật khẩu admin mặc định.</p><hr><h3 id="❌-loi-42-nham-qos-voi-tuong-lua" tabindex="-1">❌ Lỗi 42: Nhầm QoS với tường lửa <a class="header-anchor" href="#❌-loi-42-nham-qos-voi-tuong-lua" aria-label="Permalink to &quot;❌ Lỗi 42: Nhầm QoS với tường lửa&quot;">​</a></h3><p><strong>Sai:</strong> &quot;QoS dùng để chặn website không lành mạnh.&quot;</p><p><strong>Đúng:</strong> <strong>QoS (Quality of Service)</strong> ưu tiên băng thông cho các loại lưu lượng quan trọng (ví dụ: video call được ưu tiên hơn tải file). <strong>Tường lửa</strong> mới là thứ chặn/cho phép lưu lượng. QoS không chặn gì cả, chỉ điều tiết ưu tiên.</p><hr><h3 id="❌-loi-43-nghi-cap-mang-dai-bao-nhieu-cung-đuoc" tabindex="-1">❌ Lỗi 43: Nghĩ cáp mạng dài bao nhiêu cũng được <a class="header-anchor" href="#❌-loi-43-nghi-cap-mang-dai-bao-nhieu-cung-đuoc" aria-label="Permalink to &quot;❌ Lỗi 43: Nghĩ cáp mạng dài bao nhiêu cũng được&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Dùng cáp Ethernet 200m nối từ router sang phòng kho.&quot;</p><p><strong>Đúng:</strong> Cáp UTP (Cat5e/Cat6) có giới hạn tối đa <strong>100m</strong> cho Ethernet Gigabit. Vượt quá 100m, tín hiệu suy giảm gây lỗi dữ liệu. Giải pháp: dùng Fiber (cáp quang) cho khoảng cách xa hơn, hoặc đặt thêm Switch làm relay.</p><hr><h3 id="❌-loi-44-nghi-ket-noi-voi-router-nghia-la-co-internet" tabindex="-1">❌ Lỗi 44: Nghĩ &quot;kết nối với router&quot; nghĩa là có Internet <a class="header-anchor" href="#❌-loi-44-nghi-ket-noi-voi-router-nghia-la-co-internet" aria-label="Permalink to &quot;❌ Lỗi 44: Nghĩ &quot;kết nối với router&quot; nghĩa là có Internet&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Laptop tôi kết nối Wi-Fi thành công là có Internet.&quot;</p><p><strong>Đúng:</strong> Kết nối Wi-Fi thành công chỉ nghĩa là <strong>laptop và router đã liên lạc được trong LAN</strong>. Có Internet hay không phụ thuộc vào: router có kết nối với modem không, modem có hoạt động không, và ISP có đang cung cấp dịch vụ không. Đây là lý do &quot;kết nối Wi-Fi nhưng không vào được mạng&quot;.</p><hr><h3 id="❌-loi-45-nham-downlink-va-uplink" tabindex="-1">❌ Lỗi 45: Nhầm downlink và uplink <a class="header-anchor" href="#❌-loi-45-nham-downlink-va-uplink" aria-label="Permalink to &quot;❌ Lỗi 45: Nhầm downlink và uplink&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Tốc độ tải lên và tải xuống là như nhau trong gói cước của tôi.&quot;</p><p><strong>Đúng:</strong> Hầu hết gói cước gia đình là <strong>ADSL/FTTH asymmetric</strong> – tải xuống (downlink) nhanh hơn tải lên (uplink) nhiều lần. Gói 100/20 Mbps = tải xuống 100 Mbps, tải lên 20 Mbps. Chỉ có gói <strong>symmetric</strong> (dành cho doanh nghiệp) mới có hai chiều bằng nhau.</p><hr><h3 id="❌-loi-46-nghi-mac-address-co-the-xac-đinh-vi-tri-đia-ly" tabindex="-1">❌ Lỗi 46: Nghĩ MAC address có thể xác định vị trí địa lý <a class="header-anchor" href="#❌-loi-46-nghi-mac-address-co-the-xac-đinh-vi-tri-đia-ly" aria-label="Permalink to &quot;❌ Lỗi 46: Nghĩ MAC address có thể xác định vị trí địa lý&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Biết địa chỉ MAC của ai là tìm được nhà họ.&quot;</p><p><strong>Đúng:</strong> MAC address chỉ hoạt động trong <strong>phạm vi LAN</strong>. Không thể dùng MAC để xác định vị trí địa lý. Tuy nhiên, <strong>Wi-Fi probe requests</strong> (yêu cầu quét mạng) chứa MAC address – một số hệ thống thu thập probe requests để theo dõi sự di chuyển trong không gian vật lý (ví dụ: trong trung tâm thương mại).</p><hr><h3 id="❌-loi-47-nham-giua-ket-noi-wired-va-wireless-trong-cung-mot-lan" tabindex="-1">❌ Lỗi 47: Nhầm giữa kết nối wired và wireless trong cùng một LAN <a class="header-anchor" href="#❌-loi-47-nham-giua-ket-noi-wired-va-wireless-trong-cung-mot-lan" aria-label="Permalink to &quot;❌ Lỗi 47: Nhầm giữa kết nối wired và wireless trong cùng một LAN&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Máy dùng dây và máy dùng Wi-Fi ở hai mạng khác nhau.&quot;</p><p><strong>Đúng:</strong> Nếu cùng router, cả thiết bị dây (qua switch) và Wi-Fi đều thuộc <strong>cùng một mạng LAN</strong> (cùng dải IP <code>192.168.1.x</code>). Chúng giao tiếp được với nhau bình thường. Router hiện đại bridge mạng có dây và không dây thành một LAN duy nhất.</p><hr><h3 id="❌-loi-48-nghi-router-phai-khoi-đong-lai-thuong-xuyen-đe-hoat-đong-tot" tabindex="-1">❌ Lỗi 48: Nghĩ router phải khởi động lại thường xuyên để hoạt động tốt <a class="header-anchor" href="#❌-loi-48-nghi-router-phai-khoi-đong-lai-thuong-xuyen-đe-hoat-đong-tot" aria-label="Permalink to &quot;❌ Lỗi 48: Nghĩ router phải khởi động lại thường xuyên để hoạt động tốt&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Mạng chậm là do router cần khởi động lại, phải tắt mở hàng ngày.&quot;</p><p><strong>Đúng:</strong> Router hiện đại được thiết kế để <strong>chạy liên tục hàng tháng, hàng năm</strong>. Cần khởi động lại khi: áp dụng firmware update, lỗi phần mềm tạm thời, hoặc xử lý sự cố mạng. Khởi động lại hàng ngày không cần thiết và không cải thiện hiệu năng nếu thiết bị đang hoạt động bình thường.</p><hr><h3 id="❌-loi-49-nghi-đia-chi-ip-chi-dung-cho-may-tinh" tabindex="-1">❌ Lỗi 49: Nghĩ địa chỉ IP chỉ dùng cho máy tính <a class="header-anchor" href="#❌-loi-49-nghi-đia-chi-ip-chi-dung-cho-may-tinh" aria-label="Permalink to &quot;❌ Lỗi 49: Nghĩ địa chỉ IP chỉ dùng cho máy tính&quot;">​</a></h3><p><strong>Sai:</strong> &quot;Chỉ máy tính mới có địa chỉ IP.&quot;</p><p><strong>Đúng:</strong> Bất kỳ thiết bị nào kết nối vào mạng đều cần địa chỉ IP: điện thoại, máy in, camera IP, TV thông minh, tủ lạnh thông minh (IoT), router, switch managed... Thậm chí router có <strong>hai địa chỉ IP</strong>: một phía WAN (từ ISP) và một phía LAN (địa chỉ gateway nội bộ).</p><hr><h3 id="❌-loi-50-nham-protocol-va-port" tabindex="-1">❌ Lỗi 50: Nhầm protocol và port <a class="header-anchor" href="#❌-loi-50-nham-protocol-va-port" aria-label="Permalink to &quot;❌ Lỗi 50: Nhầm protocol và port&quot;">​</a></h3><p><strong>Sai:</strong> &quot;HTTP và cổng 80 là một.&quot;</p><p><strong>Đúng:</strong> <strong>Protocol (giao thức)</strong> định nghĩa <strong>cách</strong> truyền dữ liệu (HTTP quy định định dạng request/response web). <strong>Port (cổng)</strong> là <strong>số nhận dạng dịch vụ</strong> trên máy chủ. HTTP thường dùng port 80 theo quy ước, nhưng có thể chạy trên bất kỳ port nào (ví dụ: <code>http://server:8080</code>). Port 80 chỉ là giá trị mặc định.</p>`,299)])])}const p=t(a,[["render",r]]);export{d as __pageData,p as default};
